#!/usr/bin/env python3
"""Generate src/flags_gen.hpp and docs/FLAGS.md from config/flags.yaml (the single registry of TQLLM_* flags).

--check: fail if the generated files are stale, if code reads a TQLLM_* variable that is not registered, or if a
registered flag is read nowhere (stdlib only; the YAML is a fixed subset: a list of name/kind/default/doc/replaced_by)."""
import pathlib, re, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
KINDS = ("user", "debug", "retired")


def load():
    flags, cur = [], None
    for raw in (ROOT / "config/flags.yaml").read_text().splitlines():
        line = raw.split(" #")[0].rstrip() if not raw.lstrip().startswith("#") else ""
        m = re.match(r"\s*-\s*name:\s*(\S+)$", line)
        if m:
            cur = {"name": m.group(1), "kind": "", "default": "", "doc": "", "replaced_by": ""}
            flags.append(cur)
            continue
        m = re.match(r"\s+(kind|default|doc|replaced_by):\s*(.*)$", line)
        if m and cur is not None:
            v = m.group(2).strip()
            if v.startswith('"') and v.endswith('"'):
                v = v[1:-1].replace('\\"', '"').replace("\\\\", "\\")
            cur[m.group(1)] = v
    for f in flags:
        assert f["kind"] in KINDS, f
    return flags


def cstr(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def gen_hpp(flags):
    rows = ",\n".join(
        f"    {{{cstr(f['name'])}, Kind::{f['kind'].capitalize()}, {cstr(f['default'])}, {cstr(f['doc'])}, {cstr(f['replaced_by'])}}}"
        for f in flags)
    return f"""// Generated by tools/gen_flags.py from config/flags.yaml - do not edit.
#pragma once
#include <cstring>

namespace tqllm::flags {{
enum class Kind {{ User, Debug, Retired }};
struct Flag {{
    const char * name;
    Kind kind;
    const char * def;
    const char * doc;
    const char * replaced_by;
}};
inline constexpr Flag ALL[] = {{
{rows}
}};
inline const Flag * find(const char * name) {{
    for (const auto & f : ALL)
        if (std::strcmp(f.name, name) == 0) return &f;
    return nullptr;
}}
}}  // namespace tqllm::flags
"""


def gen_md(flags):
    out = ["# TQLLM flags", "", "Generated from `config/flags.yaml` (`tools/gen_flags.py`). `tqserve --list-flags` prints the same table;",
           "every tool stops at start-up when a retired name is set and warns about unknown `TQLLM_*` names. Settings are",
           "command-line options (`docs/CONFIG.md`).", ""]
    titles = {"user": "Environment", "debug": "Debug", "retired": "Retired (the tool stops; use the replacement)"}
    for k in KINDS:
        out += [f"## {titles[k]}", "", "| Flag | Default | What it does | Use instead |", "|---|---|---|---|"]
        out += [f"| `{f['name']}` | {f['default']} | {f['doc']} | {f['replaced_by']} |" for f in flags if f["kind"] == k]
        out.append("")
    return "\n".join(out)


def used_names():
    names = set()
    for p in list(ROOT.glob("src/**/*.[ch]pp")) + list(ROOT.glob("tools/**/*.[ch]pp")) + list(ROOT.glob("kernels/**/*.cu*")) + \
             list(ROOT.glob("kernels/**/*.hpp")):
        if p.name == "flags_gen.hpp":
            continue
        names |= set(re.findall(r'"(TQLLM_[A-Z0-9_]+)"', p.read_text(errors="ignore")))
    return names


def main():
    flags = load()
    hpp, md = gen_hpp(flags), gen_md(flags)
    targets = {ROOT / "src/flags_gen.hpp": hpp, ROOT / "docs/FLAGS.md": md}
    if "--check" not in sys.argv:
        for p, t in targets.items():
            p.write_text(t)
        print(f"wrote {len(flags)} flags")
        return 0
    bad = [str(p.relative_to(ROOT)) + " is stale (run tools/gen_flags.py)" for p, t in targets.items() if not p.exists() or p.read_text() != t]
    reg = {f["name"] for f in flags}
    used = used_names()
    bad += [f"{n} is read in the code but not in config/flags.yaml" for n in sorted(used - reg)]
    retired = {f["name"] for f in flags if f["kind"] == "retired"}
    bad += [f"{n} is retired but still read in the code" for n in sorted(used & retired)]
    bad += [f"{n} is registered but read nowhere" for n in sorted(reg - used - retired)]
    for b in bad:
        print("FLAGS:", b)
    print("flags registry:", "FAIL" if bad else f"ok ({len(flags)} flags)")
    return 1 if bad else 0


sys.exit(main())
